from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    centers = []

    # Each colored tile is an isolated solid rectangle separated by blank
    # gutters. Its center cell carries the tile's symbol.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            # Ignore edge-clipped tiles; only complete square tiles vote.
            if y1 - y0 != x1 - x0 or len(cells) != (y1-y0+1)*(x1-x0+1):
                continue
            cy, cx = (y0+y1)//2, (x0+x1)//2
            centers.append((cy, cx, grid[cy][cx]))

    if not centers:
        return out
    frequency = Counter(color for _, _, color in centers)
    common = frequency.most_common(1)[0][0]
    for color in frequency:
        if color == common:
            continue
        # Extend matching non-default tile centers horizontally/vertically;
        # draw only through blank cells, preserving all tile pixels.
        for r in range(h):
            cols = [c for y, c, col in centers if y == r and col == color]
            if len(cols) > 1:
                for c in range(min(cols), max(cols)+1):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c in range(w):
            rows = [r for r, x, col in centers if x == c and col == color]
            if len(rows) > 1:
                for r in range(min(rows), max(rows)+1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
