def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            cy, cx = (y0+y1)//2, (x0+x1)//2
            centers.append((cy, cx, grid[cy][cx]))
    if not centers:
        return out
    freq = Counter(v for _, _, v in centers)
    ordinary = freq.most_common(1)[0][0]
    for color in freq:
        if color == ordinary:
            continue
        # Extend along each row/column occupied by this marker color. Markers
        # may be single pixels or solid patches; only blank cells are painted.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            if len(cols) >= 2:
                for c in range(min(cols), max(cols)+1):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 2:
                for r in range(min(rows), max(rows)+1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
